"""
LibFuzzer-style fuzz driver for Arrow library.
Focus: DateTime parsing functionality
"""

import sys
import atheris
import arrow
from arrow import parser

@atheris.instrument_func
def fuzz_arrow_get(data):
    """Fuzz arrow.get() with various string inputs"""
    try:
        # Try to parse the input as a datetime string
        arrow.get(data.decode('utf-8', errors='ignore'))
    except (ValueError, TypeError, AttributeError):
        # Expected for invalid inputs
        pass
    except Exception:
        # Catch other exceptions to prevent crashes
        pass

@atheris.instrument_func
def fuzz_arrow_parser(data):
    """Fuzz DateTimeParser.parse() with format strings"""
    try:
        # Split the data into two parts: one for datetime string, one for format
        if len(data) > 1:
            mid = len(data) // 2
            dt_str = data[:mid].decode('utf-8', errors='ignore')
            fmt_str = data[mid:].decode('utf-8', errors='ignore')

            p = parser.DateTimeParser()
            p.parse(dt_str, fmt_str)
    except (ValueError, TypeError, AttributeError, KeyError):
        # Expected for invalid inputs
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_arrow_iso_parse(data):
    """Fuzz ISO 8601 parsing"""
    try:
        iso_str = data.decode('utf-8', errors='ignore')
        p = parser.DateTimeParser()
        p.parse_iso(iso_str)
    except (ValueError, TypeError, AttributeError):
        pass
    except Exception:
        pass

def TestOneInput(data):
    """Main fuzzing function"""
    if len(data) == 0:
        return

    # Randomly choose which fuzzing function to call
    choice = data[0] % 3

    if choice == 0:
        fuzz_arrow_get(data[1:])
    elif choice == 1:
        fuzz_arrow_parser(data[1:])
    else:
        fuzz_arrow_iso_parse(data[1:])

if __name__ == "__main__":
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

