"""
LibFuzzer-style fuzz driver for Black library.
Focus: Python code formatting functionality
"""

import sys
import atheris
import black
from black import FileMode, format_str

@atheris.instrument_func
def fuzz_black_format(data):
    """Fuzz black.format_str() with Python code"""
    try:
        code = data.decode('utf-8', errors='ignore')

        # Try to format the code with default settings
        mode = FileMode()
        result = format_str(code, mode=mode)

        # Also try formatting with some variations
        if len(code) > 0:
            # Try with different line lengths
            if len(code) % 2 == 0:
                mode = FileMode(line_length=80)
                format_str(code, mode=mode)
            else:
                mode = FileMode(line_length=120)
                format_str(code, mode=mode)

    except black.NothingChanged:
        # Expected when input is already formatted
        pass
    except (ValueError, TypeError, AttributeError, SyntaxError):
        # Expected for invalid inputs
        pass
    except Exception:
        # Catch unexpected exceptions
        pass

@atheris.instrument_func
def fuzz_black_lib2to3_parse(data):
    """Fuzz lib2to3_parse() with Python code"""
    try:
        code = data.decode('utf-8', errors='ignore')
        from black.parsing import lib2to3_parse

        # Try parsing with default target versions
        lib2to3_parse(code, target_versions=set())
    except (ValueError, TypeError, AttributeError, SyntaxError):
