"""
LibFuzzer-style fuzz driver for IPython library.
Focus: Code parsing and magic command processing
"""

import sys
import atheris
from IPython.core.compilerop import CachingCompiler
from IPython.core.inputtransformer2 import (
    TransformerManager,
    cell_magic,
    PromptStripper,
    _find_assign_op,
)
import tokenize
import io

@atheris.instrument_func
def fuzz_caching_compiler(data):
    """Fuzz CachingCompiler.ast_parse() with Python code"""
    try:
        code = data.decode('utf-8', errors='ignore')
        compiler = CachingCompiler()

        # Try to parse the code
        try:
            compiler.ast_parse(code)
        except SyntaxError:
            # Expected for invalid syntax
            pass
    except (ValueError, TypeError, AttributeError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_prompt_stripper(data):
    """Fuzz PromptStripper with various input lines"""
    try:
        text = data.decode('utf-8', errors='ignore')
        lines = text.split('\n')

        stripper = PromptStripper()
        try:
            stripper(lines)
        except Exception:
            pass
    except (ValueError, TypeError, AttributeError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_transformer_manager(data):
    """Fuzz TransformerManager with code input"""
    try:
        code = data.decode('utf-8', errors='ignore')
        tm = TransformerManager()

        # Try to transform the code
        try:
            tm.transform_cell(code)
        except (SyntaxError, ValueError):
            # Expected for invalid inputs
            pass
    except (TypeError, AttributeError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_tokenize(data):
    """Fuzz tokenization with code input"""
    try:
        code = data.decode('utf-8', errors='ignore')
        tokens = list(tokenize.generate_tokens(io.StringIO(code).readline))

        # Try to find assignment operators
        try:
            _find_assign_op(tokens)
        except Exception:
            pass
    except (ValueError, TypeError, AttributeError, tokenize.TokenError, IndentationError):
        pass
    except Exception:
        pass

def TestOneInput(data):
    """Main fuzzing function"""
    if len(data) == 0:
        return

    choice = data[0] % 4

    if choice == 0:
        fuzz_caching_compiler(data[1:])
    elif choice == 1:
        fuzz_prompt_stripper(data[1:])
    elif choice == 2:
        fuzz_transformer_manager(data[1:])
    else:
        fuzz_tokenize(data[1:])

if __name__ == "__main__":
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

