"""
LibFuzzer-style fuzz driver for UltraJSON library.
Focus: JSON parsing and encoding functionality
"""

import sys
import atheris
import ujson

@atheris.instrument_func
def fuzz_ujson_decode(data):
    """Fuzz ujson.decode() with JSON-like strings"""
    try:
        json_str = data.decode('utf-8', errors='ignore')

        # Try to decode the JSON
        try:
            ujson.decode(json_str)
        except ValueError:
            # Expected for invalid JSON
            pass
    except (TypeError, AttributeError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_ujson_encode(data):
    """Fuzz ujson.encode() with various Python objects"""
    try:
        if len(data) == 0:
            return

        # Create various test objects from the data
        test_objects = [
            data.decode('utf-8', errors='ignore'),  # String
            list(data),  # List of bytes
            {"key": data.decode('utf-8', errors='ignore')},  # Dict
            [1, 2, 3, data[0] if data else 0],  # Mixed list
        ]

        for obj in test_objects:
            try:
                ujson.encode(obj)
            except (ValueError, TypeError, OverflowError):
                # Expected for some object types
                pass
    except (AttributeError, IndexError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_ujson_with_options(data):
    """Fuzz ujson.encode() with various options"""
    try:
        if len(data) < 1:
            return

        json_str = data.decode('utf-8', errors='ignore')
        choice = data[0] % 4

        obj = {"test": json_str, "value": 123, "nested": {"key": "value"}}

        try:
            if choice == 0:
                ujson.encode(obj, encode_html_chars=True)
            elif choice == 1:
                ujson.encode(obj, escape_forward_slashes=True)
            elif choice == 2:
                ujson.encode(obj, ensure_ascii=True)
            else:
                ujson.encode(obj)
        except (ValueError, TypeError, OverflowError):
            pass
    except (AttributeError, IndexError):
        pass
    except Exception:
        pass

