    """Main fuzzing function"""
    if len(data) == 0:
        return

    choice = data[0] % 3

    if choice == 0:
        fuzz_ujson_decode(data[1:])
    elif choice == 1:
        fuzz_ujson_encode(data[1:])
    else:
        fuzz_ujson_with_options(data[1:])

if __name__ == "__main__":
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

