"""
LibFuzzer-style fuzz driver for MiniSGL library.
Focus: Request handling and configuration validation
"""

import sys
import atheris
from dataclasses import dataclass
from typing import Optional

# Import the library components that can be fuzzed
try:
    from minisgl.core import SamplingParams, Req
except ImportError:
    # If import fails, define mock classes
    @dataclass
    class SamplingParams:
        temperature: float = 1.0
        top_p: float = 1.0
        top_k: int = -1
        max_tokens: Optional[int] = None

    @dataclass
    class Req:
        input_ids: list
        prompt_len: int = 0

@atheris.instrument_func
def fuzz_sampling_params(data):
    """Fuzz SamplingParams initialization"""
    try:
        if len(data) < 4:
            return

        # Extract values from data
        import struct
        temperature = struct.unpack('<f', data[0:4])[0]
        temperature = max(0.0, min(2.0, abs(temperature)))  # Clamp to reasonable range

        if len(data) >= 8:
            top_p = struct.unpack('<f', data[4:8])[0]
            top_p = max(0.0, min(1.0, abs(top_p)))
        else:
            top_p = 1.0

        # Try to create SamplingParams
        try:
            params = SamplingParams(temperature=temperature, top_p=top_p)
        except (ValueError, TypeError, AttributeError):
            pass
    except (struct.error, IndexError):
        pass
    except Exception:
        pass

@atheris.instrument_func
def fuzz_req(data):
    """Fuzz Req initialization"""
    try:
        if len(data) == 0:
            return

        # Create a simple input_ids list from the data
        input_ids = list(data[:min(len(data), 100)])

        # Try to create a Req
        try:
            req = Req(input_ids=input_ids, prompt_len=len(input_ids) // 2)
        except (ValueError, TypeError, AttributeError):
            pass
    except Exception:
        pass

def TestOneInput(data):
    """Main fuzzing function"""
    if len(data) == 0:
        return

    choice = data[0] % 2

    if choice == 0:
        fuzz_sampling_params(data[1:])
    else:
        fuzz_req(data[1:])

if __name__ == "__main__":
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

